WITH source_rows (
    designation_no,
    title,
    developers,
    project_name,
    client,
    notice_date,
    usage_expiration_date,
    usage_count,
    amount_thousand,
    score,
    summary,
    disaster_prevention_score
) AS (
    VALUES
        ('550', '마이크로피티와 하이브리드 코팅재를 자동분사장치로 시공하는 콘크리트 표면보호공법', '(주)이노넥스트,(주)지엔시건설,김성수', '상도2배수분구 하수관거 종합정비 실시설계', '동작구청', '20080319', '20200317', 1, 32052, 0.6, '이 신기술은 외부유해인자 차단을 통한 내구성능 향상을 위해 자동분사장치로 무기계 마이크로퍼티(HBP(High Butadiene Powder) 및 중공형 미새 세라믹볼이 포함된 분말형 피티제)를 분사하여 콘크리트 표면을 처리한 후 하이브리드 코팅제(산화규소, 산화철 나노분말과 토르마린 미분말을 기능성 소제로 첨가하고 실리콘수지와 세라믹수지를 수열 합성하여 내알칼리성 아크릴 수지를 복합화 한 수영성 코팅제)로 처리하여 콘크리트구조물 표면을 보호하는 공법이다.', NULL),
    ('551', '교량 상부 구조물 지지용 수평 접이식 가설벤트 공법', '(주)벤트코리아,(주)수성엔지니어링', '경인 아래뱃길사업 제4공구 시설공사중 강재 동바리설치공사, 계곡신덕간국가지원지방도 확포장공사 대안설계', '한국수자원공사,전라북도', '20080327', '20200325', 2, 2384232, 1, '이 신기술은 소직재, 수평재 및 고정브레이스로 구성된 다수의 단위 모듈과 단위모듈 사이를 수직재 내에 설치된 수직홈과 가동브레이스를 연결하여, 레일빔 상부에서 수평방향으로 확장과 축소가 가능하도록 한 교량 상부 구조물 지지용 가설벨트 공법이다.', NULL),
    ('553', '고강도 프리캐스트 패널 (LB-DECK)과 전용작업 대차를 활용한 교량바닥판 시공방법', '(주)효성엘비테크,(주)한국해외기술공사', '경인아라뱃길사업 제4공구 시설 공사실시설계', '한국수자원공사', '20080612', '20200610', 1, 424655, 0.6, '이 신기술은 거더교(PSC 빔교, Steel Box 거더교, Steel I형 거더교등)의 바닥판 슬래브 시공시 고강도 콘크리트 패널과 래티스 거더(Lattice-girder)를 합성한 두께 60mm프리캐스트 패널(LB-DECK)을 작업대차로 거더와 거더 사이에 거치하고, 그 위에 바닥판의 철근배근과 콘크리트 타설작업을 할 수 있도록 한 교량 바닥판 시공공법이다.', NULL),
    ('556', '강관말뚝과 PHC말뚝을 결합구로 용접시킨 매입형 복합말뚝', '㈜파일테크,두산중공업㈜,한맥기술,㈜한국종합기술', '김포한강택지개발사업 도시시설물 조사설계용역,서울~세종고속도로안성~구리건설공사기본및실시설계용역(2공구)', '한국토지주택공사,한국도로공사', '20080728', '20210726', 2, 775172, 0.7, '이 신기술은 수평력과 모멘트가 작용하는 말뚝상부는 전단 및 휨저항능력이 우수한 광관말뚝을, 압축력이 주로 작용하는 말뚝하부는 PHC말뚝을 결합구로 용접하여 복합말뚝(HCP:Hybrid Composite Pile)을 제작하고, 이를 지반 및 하중조건 등 현장 여건에 따라 달라지는 말뚝심도에 자유롭게 대응할 수 있도록 복합말뚝의 강관 및 PHC 말뚝 길이를 조절하여 설계하고 매입하는 공법이다.', NULL),
    ('561', 'WPC(Wide flange Prestressed Concrete)박스거더교량공법', '이엔이건설(주),고려개발(주),(주)신성엔지니어링,(주)케이지엔지니어링종합건축사사무소', '서울~세종 고속도로 안성~구리건설공사 기본및실시설계용역(2공구),수도권제2순환(김포~파주)고속도로건설공사실시설계용역(5공구)', '한국도로공사', '20081114', '20211112', 2, 1639817, 0.8, '이 신기술은 U형 거더상부를 내.외측으로 확대하고 외두 강재거푸집과 내부 영구 매립거푸집을 적용함으로써 폐함 박스(BOX)형태의 확폭 플랜지단면을 형성하는거더를 맞닿게 배치하는 교량 공법으로 바닥판 시공기 거푸집과 동바리 공정을 생락하여 공기단축 및 안전사고를 예방할 수 있게 하였으며, 도로교는 지간 50m이하,철도교는 일반철도의 경우 지간 40m이하, 고속철도의 경우 지간 35m이하 구간에 적용가능한 합성형 WPC(Wide flange Prestressed Concrete)박스거더 교량건설공법이다.', NULL),
    ('644', 'AGS(Automatic Grouting System)를 이용한 그라우팅 관리기술', '(주)한국지오텍', '양재대로 지하차도 기본 및 실시설계용역', '서울특별시', '20120224', NULL, 1, 88802, 0.6, '이 신기술은 AGS(Automatic Grouting System)을 이용하여 대상지반의 특성과 주입공사의 목적에 따라서 자동으로 시험 및 시공관리를 할 수 있는 그라우팅 관리기술로, 주입지반의 시공조건평가, 주입압(p), 주입속도(q), 시간(t) chart 검측 및 지반탐사, 주입시공 자동관리, 원격 관리하는 공정으로 구성된다.', 0.9),
    ('577', '접착보강핀을 설치하고 미세분말 플라이애시 및 삼산화규산칼슘섬유가 혼입된 모르타르를 회전돌기형 믹싱샤프트건에 의해 건식분사하는 콘크리트 단면보수공법', '리플래시기술(주),김성수', '동작대교 보수 보강 실시설계 용역', '서울특별시', '20090427', '20220425', 1, 69514, 0.6, '이 신기술은 열화된 콘크리트 제거한 보수단면에 삽입핀과 사각의 메쉬형 접착보강구조물이 결합된 접착보강핀을 설치하고 미세분말 플라이에시 및 삼산 화규산칼륨섬유가 혼입된 모르타르를 타설하여 보수 콘크리트의 균열이나 들뜸을 억제하였으며, 건식, 압송장치로 모르타르 재료를 이송하고 노즐에서 압축공기와 물이 공급되는 회전돌기형 믹싱샤프트건으로 분사함으로써 이송거리를 증대시키고 재료분리 현상을 저감시킨 콘크리트 단면보수 공법이다.', 0.9),
    ('665', '슬래그 잔골재 치환 초속경LMC를 전용장비로 시공하는 교면 및 콘크리트 포장 유지보수 공법', '㈜삼우아이엠씨', '이문고가외2개소보수.보강공사실시설계', '서울특별시', '20120621', '20260619', 1, 437072, 0.6, '이 신기술은 상.하관 분리식 핑거형 신축이음장치에 있어서 상.하판 후단부에 걸침턱 구조를 두어 맞물리게 설치함으로써 볼트부의 응력을 걸침턱으로 분산시켜 볼트 풀림 및 파단현상을 저감하는 공법이다.', 0.9),
    ('737', '2단계로 확장되는 앵커체를 이용한 암반정착 앵커 공법(EJP 공법)', '(주)장평건설,(주)삼안,(주)포스코건설,(주)한국건설관리공사', '양재대로 지하차도 기본 및 실시설계용역', '서울특별시', '20140729', '20250727', 1, 92636, 0.6, '이 신기술은 인장재 선단에 정착된 확장형 앵커체를 코일스프링의 복원력에 의해 천공홀에 밀착시킨 후 인장재를 긴장하여 천공홀 주변 암반에 압력을 가하면석 정착시켜 초기 인발저항력을 확보한 다음 그라우트 주입하는 것으로, 2단계로 작동되는 확장형 앵커체가 초기 슬립을 방지하고, 지반 천공홀내에 인발력에 상응하는 확장압이 작용되어 정착됨으로써 인장재에 긴장력이 우지되어 불안정한 사면활동 회측에서 저항하여 사면의 안정성을 증대시키고, 무그라우팅 사앹에서 초기 인발성능을 확보하여 급속시공이 가능한 앵커공법이다.', 0.9),
    ('597', 'LU형으로 3차원 가공된 이형철근을 결합한 강관말뚝 두부보강공법', '(주)수성개발,(주)동아기술공사,(주)선진엔지니어링종합건축사사무소,(주)용진엔지니어링', '서울~세종(세종~안성)고속도로건설공사기본및실시설계용역(2공구)', '한국도로공사', '20100104', '20230102', 1, 86308, 0.6, '이 신기술은 강관말뚝과 확대기초를 강결시키는 두부보강공법으로 L자형과 U자형으로 3차원 가공된LU형 이형철근(LU Bar)을 강관말뚝의 상부에 천공한 장공형 구멍에 끼운 후 강관내부의 U자형 보강철근 안쪽에 띠철근을 설치하여 조립하는 강관말뚝 두부보강 공법이며, LU Bar의 L형구간은 강관말뚝의 천공부를 지나면서 철근을 통해 전달되는 하중을 강관말뚝에 직접 전달하교 U자형구간은 띠철근과 함께 강관내부 콘크리트의 보강역할을 수행한다.', 0.9),
    ('576', '친환경 모르타르와 급결제용 날개식 이중 분사장치 및 원추형노즐로 구성된 스프레이 장비를 이용한 콘크리트 구조물 급속보수공법', '(주)캐어콘,유림건설(주),(주)용마엔지니어링', '한강대교 보강 보수공사 실시설계', '서울특별시', '20090423', '20230422', 1, 1130, 0.6, '이 기술은 슬래그, 실리카흄 및 건설폐기물인 순환골재를 활용하고, 타설 초기의 부착력을 확보하기 위해서 알카리프리 급결제로 응결시간을 촉진하며, 급결제 사용에 따른 초기강도의 감소현상을 저감시키기 위해서 알카리 무기염계를 이용한 친환경 모르타르를 사용한다. 또한 스퀴즈 펌프를 이용한 모르타르용 스프레이 장비에 급결제를 투입 할 수 있는 날개식 이중 분사장치를 설치하고, 압축공기가 유입되는 내부의 홈을 부채꼴의 나선형태로 특화한 원추형 노즐로 구성함으로써 일정한 압력으로 모르타르와 타설이 가능한 콘크리트 구조물의 급속 보수 공법이다.', 0.9),
    ('582', '거더 단부의 상부에 긴장재의 이완과 재긴장이 가능한정착 시스템을 이용한 프리스트레스트 콘크리트 거더 공법', '동부건설(주),(주)한맥기술,(주)장헌산업', '서울~세종 고속도로 안성~구리건설공사 기본및실시설계용역(2공구),세종~포천(세종~안성)고속도로건설공사 기본및실시설계용역(3공구)', '한국도로공사,한국도로공사', '20090724', '20230723', 2, 997406, 0.7, '이 기술은 프리스트레스 콘크리트 거더에서 2차 긴장재의 이완과 개긴장이 가능한 정착시스템을 거도 단부의 상부에 설치하여 거더와 바닥판의 내구 수명 차이에 따라 발생하는 바닥판 교체시 거더 중앙부의 과압축 발생을 예방하고 재긴장을 통하여 거더의 성능회복은 물론 공용수명을 증진시킨 스리스트레스트 콘크리트 거더 공법이다.', 1.05),
    ('603', 'PS강선 및 강봉의 일체긴장시스템을 이용하여 프리스트레스를 도입하는 PSC거더(Bicon거더)의 제작공법', '(주)삼현피에프,(주)포스코건설,(주)유신,(재)포항산업과학연구원,한국철도기술연구원', '고속국도제600호선 부산외곽순환건설공사(제8공구)대안입찰설계용역,세종~포천(세종~안성)고속도로건설공사 기본및실시설계용역(3공구)', '한국도로공사,한국도로공사', '20100517', '20240515', 2, 2616258, 1, '본 기술은 콘크리트거더 상연에 강봉을 삽입하고 양 단부에서 PS강선과 일체긴장연결구를 이용, 일체로 연결하여 강선의 긴장시 발상하는 압축력을 강봉이 부담하고 콘크리트 거더에는 강봉과 PS강선의 거리를 편심으로 하는 순수 휠모멘트를 도입시킴으로써, 장경간. 저형고 PSC거더의 제약조건인 거더 상연의 압축응력 초과 문제를 해결할 수 있으며 다단계 긴징을 배제하고 1회의 긴장에 의해 제작될 뿐만 아니라 중립축이 낮아 가설시 전도위험이 없는 시공이 용이한 PSC거도 공법이다.', 1.5),
    ('624', '현장함침 및 롤삽입 견인식 하수관거 비굴착전체보수공법', '한국라이텍개발(주)', '성남시 하수관로 정비사업(3단계) 기본 및 실시설계 용역', '경기도 성남시', '20110609', '20250607', 1, 176275, 0.6, '이 신기술은 현장함침용 튜브를 현장함침기에서 담금,침투,짜짐방식과 분사방식으로 현장함침을 하고, 현장함침된 튜브를 롤삽입장치로 견인하여 노후 및 파손된 하수관거 재부에 삽입하여 보수하는 하수관거(D250mm~D1,000mm) 비굴착전체보수공법이다.', 0.9),
    ('627', '걸침턱 구조를 가진 상·하판 분리식 핑거형 신축이음장치 설치공법', '(주)일원테크,한국종합기술(주),동부엔지니어링(주)', '동작대교 보수 보강 실시설계 용역, 한강대교 신축이음장치 보수공사', '서울특별시,서울특별시', '20110707', '20250705', 2, 127968, 0.7, '이 신기술은 상.하관 분리식 핑거형 신축이음장치에 있어서 상.하판 후단부에 걸침턱 구조를 두어 맞물리게 설치함으로써 볼트부의 응력을 걸침턱으로 분산시켜 볼트 풀림 및 파단현상을 저감하는 공법이다.', 1.05),
    ('646', '강박스 내측 하면에 아치형상의 콘크리트를 타설한 개구형 박스(U)단면을 I형 단면의 상부에 조합하여 변단면 구조를 갖도록 한 강합성거더 공법', '혜동브릿지(주), (주)포스코건설,(주)경동엔지니어링,(주)경호엔지니어링종합건축사사무소', '국가지원지방도60호선(양산신기-유산)건설공사 실시설계용역', '부산지방국토관리청', '20120309', '20260307', 1, 2288641, 1, '이 기술은 강재거더를 지점부에서는 폐단면이고 지간 중앙부에서는 개구형박스(U)단면이 I형단면과 아치형태의 변단면 구성을 갖는 형상이며, 강박스내부에 압축 주응력이 장용하는 방향을 따라 아치형태의 콘크리트를 배치하여 이종재료의 상호보완효과로 효율적인 단면강성을 확보함에 따라 좌굴저항성 증대와 보강재를 최소화 할 수 있는 동시에 진동성능을 증대시킬 수 있는 강합성거더 공법이다.', 1.5),
    ('648', '거더 하연을 곡선화한 아치형상의 변단면 PSC-I 거더의 제작 기술(APC-빔)', '(주)에이스이엔씨,(주)도화엔지니어링,(주)이산', '서울~세종(세종~안성)고속도로건설공사기본및실시설계용역(2공구),세종~포천(세종~안성)고속도로건설공사 기본및실시설계용역(3공구)', '한국도로공사,한국도로공사', '20120316', '20270315', 2, 1028564, 0.7, '이 신기술은 본래의 PSC-I 거더의 간편한 시공성과 경제성을 살리면서 PSC-I거더 하연을 아치형을 갖도록 제작하는 기술로 경관을 고려한 교량을 건설할 수 있고, 아치효과에 의하여 균등단면의 PSC-I거더보다 처짐 및 응력감소 효과로 구조안전성을 향상시킬수 있는 변단면 PSC-I거더 제작기술이다.', 1.05),
    ('687', '견인력 저감형 유도 및 견인장치와 반전튜브의 관내 초입부증기분사 경화방식에 의한 하수관거 비굴착 전체보수공법', '(주)엔코텍,중앙산업(주)', '성남시 하수관로 정비사업(3단계) 기본 및 실시설계 용역', '경기도 성남시', '20130129', '20290127', 1, 264090, 0.6, '이 신청기술은 견인튜브와 반전튜브를 분리하여 각각의 튜브에 수지를 함침하여 튜브의 두께와 중량을 줄이고, 이동식 견인력 저감형 견인장치와 맨홀과 관입구에 설치하여 튜브손상방지를 위한 견인튜브 유도장치를 통해 견인튜브를 삽입한다. 삽입 완료 후 견인튜브내로 수지가 함침된 반전튜브를 공기압으로 삽입 시 반전기내부에 미리 설치된 열호스를 반전과 동시에 관입구까지 놓이게 한 후 반전삽입 완료 후 열원(증기열)을 공급하여 현장에서 신관을 생성하는 연성라이닝 비굴착 전체보수 기술이다.', 0.9),
    ('688', '메나지힌지를 이용하고 세미리지드파일과 복합거더를 일체화한 교량 공법', '(주)내경엔지니어링,(주)서영엔지니어링,(주)케이씨씨건설', '우이천 상류 산책로 및 교량설치 실시설계용역', '도봉구청', '20130131', '20290129', 1, 219000, 0.6, '이 신기술은 상부구조, 하부구조와 접속슬래브를 강결 일체화하여 무받침무죠인트의 다연속 프레임 구조를 구성하고, 상부구조는 강구조, PSC구조와 RC구조가 혼합하여 낮은 높이의 복합슬래브 단면으로 하며, 접속슬래브 내에 게르버힌지인 메나지장치를 설치하고, 교량시종점부에는 횡방향에 유연 및 축방향강성인 큰 단주의 세미리지드 파일으로 지지하며, 상기 말뚝과 상부 구조 연결을 강결 일체식 구조로 하거나 힌지 반일체식 구조로 구축하여 무.세미교대, 뭅받침, 무신축이음의 다연속 프레임 일체식 및 반일체식 복합 슬래브 교량 구조체를 설계, 제작 및 시공방법에 대한 기술임.', 0.9),
    ('690', '미리 제작된 고강도 콘크리트 접합블록을 접합단부로 사용하는 PSC-I형 분절거터(SegBeam)제작방법', '(주)인터컨스텍,(주)도화엔지니어링,(주)건화,(주)천일', '수도권제2순환(김포~파주)고속도로건설공사실시설계용역(5공구)', '한국도로공사', '20130131', '20300129', 1, 842108, 0.6, '이 신기술은 미리 정밀하게 제작한 접합블록을 분절거더 세그먼트의 접합전달부로 사용하는 고강도 PSC 분절거더 제작기술로서, 접합블록은 세그먼트 본체보다 높은 강도를 사용하여 분절거더 접합부의 구조적 취약성을 보강한다. 이러한 접합블록은 세그먼트 제작시 세그먼트 거푸집 내에서 세그먼트 단부 거푸집 역할울 하게 되는데, 이때 접합블록의 위치를 조장합으로서 하나의 세그먼트 거푸집으로 다양한 길이의 세그먼트 자젝이 가능하다', 0.9),
    ('696', '강봉의 연직방향 긴장시스템을 이용하여 프리스트레스를 도입한 강합성 라멘교 공법', '(주)하이드로코리아,(주)동명기술공단종합건축사사무소,(주)대우건설', '영동선 이천시 임대주택 방음시설 설치공사 실시설계용역, 남해선 광양목성지구 방음시설 설치공사 실시설계용역', '한국도로공사,한국도로공사', '20130607', '20270606', 2, 548102, 0.7, '이 신기술은 교대(벽체)에 매립 시공된 강봉이 연직 관통하도록 제작된 강재거더를 교대에 거치한 뒤, 연직방향 강봉긴장시스템을 이용하여 긴장 및 정착하여 강재거더에 프리스트레스를 현장에서 도입하여 슬래브 콘크리트 합성전에 강재거더를 단순보에서 연속보 형태로 구조계를 변경하여 발생부재력을 제어하는 강합성 라멘교 제작 공법이다', 1.05),
    ('714', '저점도 UDRS 수지(MSA-100형)와 충진 지수용 굴절식 팩커를 이용한 하수관로 비굴착 부분보수공법(UDRS공법)', '웅진고분자(주),동부엔지니어링(주)', '영주시 노후하수관로 정비사업(1단계) 기본 및 실시설계용역, 사천시 노후하수관로 정비사업 실시설계', '경상북도 영주시,경상남도 사천시', '20131129', '20281128', 2, 1216702, 0.7, '이 신기술은 파손된 하수관거의 부분보수시공이 요구되는 소형, 중·대형의 모든 하수관거에 파손, 균열, 부식, 어긋남, 이완, 이음부, 분기부, 단차부 등에 발생된 불량 및 결함부위에 지수재인 저점도 UDRS수지(MSA-100형 : 변성아크릴계 수지)와 카메라 로봇과 다기능성 무보강 충진 지수용 굴절식 팩커시스템을 이용하여 불량과 결함부위에 지수재를 주입 및 충진하여 관경 내벽·외벽부(토양)를 동시에 수지 겔(Gel) 및 모래 겔(Sand-Gel), 토양 겔(Soil-Gel)층을 만들어 보수 및 보강시공이 동시에 가능하게 한 기술로, 보수 후 침출수 및 침입수의 누수차단으로 외부 토양 유실과 지반침하를 방지하고 수밀성과 기밀성에 대한 구조적인 안정성을 증대시키며 하수관거의 관경 축소 없이 통수능력을 향상시킨 신기술로, 2차적 환경오염방지와 불투명수의 유입으로 발생되는 수처리에 대한 비용을 절감할 수 있는 지수충진 비굴착 부분 보수공법(UDRS공법)', 1.05),
    ('726', '흙막이벽체 지지를 위한 원형 강관 버팀보 체결공법(SP-STRUT공법)', '(주)핸스,(주)도화엔지니어링,(주)건화', '양재대로 지하차도 기본 및 실시설계용역', '서울특별시', '20140221', '20280220', 1, 499142, 0.6, '이 신기술은 토목(철도,지하철,지하차도), 플랜트(상하수도, 환경), 건축건설공사에서 기존 H형강 버팀보의 비해 단면의 좌굴 및 비틀림 성능이 우수한 원형의 강관 버팀보를 시공함에 있어서 띠장 연결재(HWJ-Ⅱ) 및 강관유밴드(HYB-Ⅱa)를 적용하여 가시설전체 구조계를 변경함으로써, 수평·수직·횡 보강재(bracing)가 불필요하게 되는 흙막이벽체 지지 공법이다.', 0.9),
    ('729', '충격차단공과 철근-숏크리트를 이용한 근접병설터널의 암반 필라부 시공법', '(주)하이콘엔지니어링', '서울~세종고속도로 안성~구리건설공사기본및실시설계용역(7공구),세종~포천(세종~안성)고속도로건설공사기본및실시설계용역(3공구)', '한국도로공사,한국도로공사', '20140409', '20310408', 2, 384274, 0.7, '이 신기술은 충격차단공(슬롯 드릴링,라인드릴링)을 이용한 진동제어발파기술과 철근-숏크리트를 이용하여 필라부에 대해 보강기술을 사용하여, 암반 터널 입.출구에서 터널간 이격거리를 좁히고 터널내에서 넓혀가면서 굴지하여 선.후행 터널별로 차등적인 굴착 및 보강방법을 적용하는 암반 근접병설(병렬)터널의 시공법이다.', 1.05),
    ('730', '전단돌기가 있는 띠형 유공강판 연결재를 사용한 강관말뚝 머리보강공법', '(주)지승컨설턴트,현대엔지니어링(주),(주)케이알산업,대우조선해양건설(주),(주)수성엔지니어링', '김포한강택지개발사업 도시시설물 조사설계용역,수도권제2순환(김포~파주)고속도로건선공사실시설계용역(5공구),세종~포천(세종~안성)고속도로건설공사 기본및실시설계용역(3공구)', '한국토지주택공사,한국도로공사,한국도로공사', '20140416', '20310415', 3, 49138, 0.8, '이 신기술은 강관말뚝기초에서 강관 말뚝으로 확대기초 콘크리트구조물을 지지하는 경우 사용되는 강관말뚝 머리보강공법으로, 시공된 강관말뚝의 상단을 정리한 후 말뚝 머리부에 천공기를 이용하여 다수의 구멍을 니여 관통철근을 교차 배치하고, 말뚝 내부에 속채움 콘크리트 타설을 위한 거푸집판을 설치한 후, 전단돌기(Shear key)가 있는 띠형 유공강판 연결재(Perforated Plate)를 강관말뚝의 절단면에 고정걸쇠로 수직하게 방사형 배치하고, 띠철근(원형링)으로 결합함으로써 강관말뚝과 확대기초 간의 강결합을 확보하는 강관말뚝 머리보강공법(Crown Cap 공법)이다.', 1.2),
    ('740', '재활용 천연라텍스 고점착 방수재와 현장타설 콘크리트 구조체 부착형 방수재를 이용한 지하구조물의 온통 GTR 외방수공법', '(주)리뉴시스템', '새만금 남북도로 건설공사 1단계(4공구) 설계, 시공 일괄입찰 용역', '새만금개발청', '20140819', '20310818', 1, 828087, 0.6, '이 신기술은 ①친환경+자원재활용 방수재료 및 공법 개발(터보시트 GTR), ②방수 안정성 확보를 위해 지하구조물 바닥 부위에 대한 현장 타설 콘크리트 일체 부착형 방수재료 및 공법 개발(Pre-GTR), ③접합부 전용 시공 장비(Joint Roller) 및 취약부 전용 보강 소재(GTR Gel) 개발, ④시공안정성 개선을 위한 별도의 바탕 정리 미실시 및 프라이머 미사용 · 위험요소 제거 방안을 목표로 개발되었으며, 현재 뿐만 아니라 미래에도 방수산업 분야에서 요구하는 다양한 조건을 만족시킬 수 있도록 한 “온통 GTR 외방수공법”이다.', 0.9),
    ('750', '이산화탄소와 염소이온 고정 고알칼리유기체 방청제, 방처표면피복제 및 방청단면복구재를 사용한 철근콘크리트구조물 보수공법(BNB공법)', '(주)비앤비,(주)건화,(주)도화엔지니어링,(재)한국건설품질연구원', '발산역 지하보도 에스컬레이터 실치외 BOX 정비공사 실시설계용역, 새만금 남북도로 건설공사 1단계(4공구) 설계, 시공 일괄입찰 용역', '강서구청,새만금개발청', '20141219', '20301217', 2, 165818, 0.7, '이 신기술은 이산화탄소(CO2)와 염소이온(CI)을 화학적으로 고정하는 고알칼리 유기체 방청제(아미노알콜 유도제이용), 방청표면피복재 및 방청단면복구재를 사용하는 철근콘크리트구조물 보수공법으로, 탄산화 및 염해에 의하여 피복 콘크리트가 손상되었거나 철근이 부식하여 콘크리트가 박리. 박락한 철근콘크리트구조물을 보수하는 기술이다.', 1.05),
    ('751', '보강리브와 헌치 및 파형철선 전단연결재를 이횽한 교량용 프리캐스트 콘크리트 바닥판 공법(Rib-Deck공법)', '(주)신원RPC,(주)삼안,(주)한진중공업,(주)경호엔지니어링종합건축사사무소', '수도권제2순환(김포~파주)고속도로건선공사실시설계용역(5공구)', '한국도로공사', '20141222', '20321220', 1, 321155, 0.6, '이 신기술은 프리캐스트 콘크리트 패널의 하면에 보강리브가 일체로 형성되어 패널의 강성이 증가되고 증가된 패널 강성으로 긴장력등의 도입 없이 거더 사이의 간격이 2.7m를 초과하는 경우에도 적용 가능하며, 일단부 또는 양단부에 헌치를 일체로 형성하여 종.횡방향의 구배조절이 용이하고 현장타설 콘크리트 물량을 감소할 수 있으며, 파형 전단연결재를 적용하여 현장 바닥판 철근 배근 시공성이 향상된 교량용 프리캐스트 콘크리다 바닥판 공법이다.', 0.9),
    ('763', '접합부에 횡방향 연결재를 설치하고 횡방향으로 긴장한 바닥판 일체식 프리캐스트 PSC 박스거더', '현대건설(주),브릿지테크놀러지(주),(주)케이알티씨,연세대학교산학협력단', '새만금 남북도로 건설공사 1단계(4공구) 설계, 시공 일괄입찰 용역', '새만금개발청', '20150420', '20320418', 1, 1297967, 0.6, '이 신기술은 바닥판 일체식 중공형의 PSC 박스거더를 병렬로 밀착하여 거치한 후 박스거더 사이의 횡방향 연결구간에 경사각을 갖는 강관연결재(Easy-bar) 및 철근 이음을 설치하고 콘크리트를 타설한 후 일정간격으로 배치된 횡방향 강연선을 긴장하여 상부거더를 일체화시키는 프리캐스트 PSC 박스거더로서, 저형고 및 급속시공이 가능하고 편측 캔틸레버를 갖는 외측거더를 적용함으로써 캔틸레버 길이 변화로 곡선교의 곡률반경 적용이 가능하며 횡방향 인접 교량의 시공시 횡방향 긴장을 위한 작업공간 확보가 가능한 기술이다.', 0.9),
    ('768', '원형체결판을이용한 무용접 무볼트 방식 강관말뚝머리보강공법(Disk Connector공법)', '(주)동명기술공단종합건축사사무소,두산건설(주),대보건설(주),장일영', '서울~세종고속도로 안성~구리건설공사기본및실시설계용역(7공구),세종~포천(세종~안성)고속도로건설공사기본및실시설계용역(3공구)', '한국도로공사,한국도로공사', '20150703', '20300701', 2, 30758, 0.7, '이 신기술은 원형체결판과 방사상으로 조립된 L자형 철근을 이용한 강관말뚝 머리보강 공법으로, 작업공장의 최소화를 목적으로 원형체결판을 활용하여 급속시공을 함으로써 현장에서의 용접, 볼트조립 등의 복잡한 설치공정을 배제하고 가공된 철근을 삽입하는 손쉽고 시공이 빠른 공법이다.', 1.05),
    ('774', '거더 양측 단부에 돌출된 별체를 갖는 단부격벽일체형 PSC 거더를 사용한 반일체식 교량 공법', '(주)지승씨앤아이,롯데건설(주),대우조선해양건설(주),(주)이산,(주)건화', '김포한강택지개발사업 도시시설물 조사설계용역,서울~세종 고속도로 안성~구리건설공사 기본및실시설계용역(2공구),경산시 국도대체우회도로 남산-하양2 건설공사 기본 및 실시설계용역', '한국토지주택공사,한국도로공사,부산지방국토관리청', '20150716', '20320714', 3, 2918934, 1, '이신기술은 거더 양측단부에 돌출된 벽체를 갖는 단부격벽일체형 프리스트레스트콘크리트(PSC)거더를 제작 거치하고, 거더의 단부격벽 사이에 무수축 콘크리트를 타설하여 일체화시키는 단부격벽 일체형PSC거더를 사용한 반일체식 교량 공법으로, 교대 배면에 무다짐 뒤채움 시공과 포장부에 신축조절장치(CCJ)를 설치하는 기술이다.', 1.5),
    ('789', 'EVA시트 방수층 하부에 수팽창하는 아크릴레이트를 합지한 건식 비노출 방수공법', '(주)흥신,(주)흥신이엔씨,대구도시철도공사', '양재대로 지하차도 기본 및 실시설계용역', '서울특별시', '20160511', '20290510', 1, 936419, 0.6, '이 신기술은 재활용 소재를 활용한 에틸렌아세트산 비닐 수지계(ethylene-vinyl acetate)시트 방수층 하부에 수팽창하는 기능을 활용하여 시트파손에 대한 자가 보수 특성을 지닌 아크릴레이트를 합지한 1℃이상, 내부 포수 표면건조 상태에서 시공가능한 건식 비노출 방수공법이다.', 0.9),
    ('794', '현장조립형 공기압 또는 수압 반전장치를 이용한 하수관 비굴착 전체보수 공법(MILS공법)', '(주)신이앤씨,(주)부명건설산업', '서귀포 보목, 토평 하수관로 정비사업 실시설계용역,영주시 노후하수관로 정비사업(1단계) 기본 및 실시설계용역', '제주특별자치도 상하수도본부,경상북도 영주시', '20160728', '20300727', 2, 1619702, 0.8, '이 신기술은 상ㆍ하 개폐수단을 갖는 현장조립형 공기압 또는 수압 반전장치를 이용하여 튜브를 기존관(D200mm~D1,500mm)에 반전 밀착하는 하수관 비굴착 전체보수공법(MILS:Multi-Inversion Lining System)이다.', 1.2),
    ('820', '분말수지와 폴리화이버로 개질시킨 시멘트를 이용한 콘크리트와 자체 개량한 장비를 이용한 교단포장 공법(PCMC)공법', '(주)상봉이엔씨,(주)콘텍이엔지,(주)한국건설관리공사', '양재대로 지하차도 기본 및 실시설계용역', '서울특별시', '20170705', '20310704', 1, 275848, 0.6, '이 신기술은 EVA분말수지와 PVA폴리화이버를 무중력 혼합장치로 프리믹스한 시멘트 및 라텍스가 배합된 폴리머 시멘트 개질 콘크리트(PCMC)와 자체 개량한 장비(마이크로 밀링장비, 자동화된 모빌믹서, 진동다짐이 가능한 콘크리트 롤러페이버)를 이용한 교면포장 공법이다.', 0.9),
    ('875', '체결형 패널(열연강판)과 접이식 버팀 보로 구성된 조립식 트렌치형 굴착공법', '(주)세기엔지니어링', '전남남부권 광역상수도 관로복선화사업(1차) 기본 및 실시설계 용역', '한국수자원공사', '20191022', '20271021', 1, 93926, 0.6, '흙막이 패널(열연강판) 양 단부에 암부와 수부가 있어 이웃하는 패널과 연속적으로 연결되고, 패널 평면부에 부착된 너트형 구조에 고장력 볼트로 버팀 레일이 거치 또는 해체되며, 마주보는 패널의 레일에 버팀보가 설치되는 기술로서 핀(환봉)을 이용해 버팀보의 높이 조절 및 고정이 가능하여 배면 토압에 저항하기 위해 터파기 전 버팀 보를 설치할 수 있으며, 버팀 보의 중앙과 양단의 연결부가 접이식 Hinge로 되어있어 버팀 보 해체가 용이한 공법', 0.9),
    ('876', 'H파일과 프리캐스트 콘크리트 조립식 벽체를 이용한 연직벽 공법', '동아이엔지(주)', '휴게소 기준미달 변속차로 개량공사 실시설계 용역,기준미달 변속차로 개량공사 실시설계 용역(1권역)', '한국도로공사,한국도로공사', '20191119', '20271118', 2, 1596636, 0.7, '본 신기술은 H파일을 기초저판 없이 지반에 설치하여 기초 안정성을 확보하고, 프리캐스트 콘크리트 조립식 벽체의 중공부에 지표면에 돌출된 H파일이 매립되도록 조립한 후 무수축 그라우트를 충진하여 결합하는 연직벽 시공기술로서, 접합시공시 선형, 간격, 수직도에 대한 벽체 제작오차 및 시공오차를 수용하면서 시공이 가능하고, 프리캐스트 콘크리트 조립식 벽체끼리의 종방향 연결은 커플러와 스플라이스 플레이트 또는 유공관 연결재를 사용하여 시공성 개선 및 강성을 확보할 수 있음 조립식 벽체는 공장에서 사전 제작하여 현장에서 신속하게 조립하는 프리캐스트 콘크리트 구조로 공기단축이 가능하고, 기초저판이 없는 구조로 토공사의 감소가 가능하며, 협소한 작업공간에서도 시공이 가능하여 운행 중인 도로 및 철도 현장 등에서도 주변 지장물 및 교통간섭을 최소화할 수 있는 시공법임', 1.05),
    ('888', '벽체와 기초 앞굽을 PS강봉으로 일체화한 역T형 프리캐스트 옹벽', '(주)강탄산업', '휴게소 기준미달 변속차로 개량공사 실시설계 용역', '한국도로공사', '20200528', '20280527', 1, 191664, 0.6, '이 기술은 공장에서 벽체와 기초 뒷굽을 일체로 제작하여 차량 운반이 가능하게 하고, 현장에서 PS강봉(Prestressing Steel Threadbar)으로 긴장력을 도입하여 기초 앞굽을 강결함으로써 철근콘 크리트 옹벽(높이 7.0m 이하)을 완성하는 직접기초형식의 역T형 프리캐스트 콘크리트 옹벽 공법임.', 0.9),
    ('917', '고함량 부틸고무를 활용한 컴파운드와 합성고분자계3증 교차필름을 이용한 비노출 방수공법(SMART POWER SYSTEM)', '(주)삼성건업', '도시안전종합시설조성 기본 및 실시설계 용역,양재천근린공원 공영주차장 건설공사 설계용역', '서울특별시 은평구,서울특별시 서초구', '20210624', '20290623', 2, 686050, 0.7, '이 신기술은 기존 자착식 방수시트 컴파운드의 주원료인 아스팔트를 배제하고 고함량 부틸고무(45%이상)로 대체함에 따라 기존 아스팔트 함유시 유분이 콘크리트 표면에 흡착되는 탈유 현상 및 아스팔트에서 분리된 유분이 컴파운드 표면으로 유출되는 유막현상을 방지함으로써 방수시트의 유연성 상실(갈라짐 등) 과 이로 인한 방수기능 상실 등의 문제와 시공 시 콘크리트 바탕면과 접착력 저하로 인한 들뜸, 박리,박락 문제를 근본적으로 해결 하였으며, 컴파운드 상부에 합지되는 필름을 강도가 높은 PET 필름 하부에 신율이 높은 PE 필름을 2중교차 합지한 합성고분자계 3중교차 필름을 적용함으로써 방수시트의 양방향 인장강도 및 신장률을 동시에 확보한 고내구성의 스마트 파워시트를 적용하여 장기적으로 방수안정성 및 내구성을 향상시킨 비노출 방수공법(SMART POWER SYSTEM)이다.', 1.05),
    ('954', '실시간 전도 위험경보가 가능한 loT센서 기반 스마트 모니터링 기술', '(주)케이씨티이엔씨,삼부토건(주),디엘건설(주),(주)하나이엔씨', '양재천근린공원 공영주차장 건설공사 설계용역', '서울특별시 서초구', '20230109', '20310108', 1, 243392, 0.6, '이 신기술은 블루투스5 기반의 MEMS무선센서와 무선 게이트웨이를 이용하여 가시설, 옹벽 등 건설 구조물의 전도 위험을 실시간으로 감시하고 위험 발생 시 근로자와 관리자, 시민에게 즉각적으로 실시간 경보를 전달하는 스마트 안전 솔루션이다. 실시간 측정 및 경보, 오경보 발생 방지 기능, 센서 무선 스캐닝 등록 기능, EMC무선통신기술 등의 핵심 기술과 모바일 앱과 소프트 웨어를 통한 원격 점검 및 제어 등을 통하여 건설현장 내 구조물의 안전관리와 시스템 시공 및 유지관리 효율 향상이 가능한 IoT기반의 모니터링 기술이다.', 0.9),
    (NULL, '합    계', NULL, NULL, NULL, NULL, NULL, NULL, 16257476, 15.4, NULL, 23.1)
)
INSERT INTO new_technology_usages (
    designation_no,
    title,
    developers,
    project_name,
    client,
    notice_date,
    usage_expiration_date,
    usage_count,
    amount_thousand,
    score,
    summary,
    disaster_prevention_score,
    created_id,
    last_changed_id
)
SELECT
    designation_no,
    title,
    developers,
    project_name,
    client,
    notice_date,
    usage_expiration_date,
    usage_count,
    amount_thousand,
    score,
    summary,
    disaster_prevention_score,
    'migration',
    'migration'
FROM source_rows source
WHERE NOT EXISTS (
    SELECT 1
    FROM new_technology_usages existing
    WHERE existing.designation_no = source.designation_no
      AND existing.title = source.title
      AND COALESCE(existing.project_name, '') = COALESCE(source.project_name, '')
);
